diff --git a/src/io/sales-import.js b/src/io/sales-import.js
new file mode 100644
index 0000000..410fbd9
--- /dev/null
+++ b/src/io/sales-import.js
@@ -0,0 +1,84 @@
+// Importing till sales from CSV (ticket,soldAt,dishId,qty).
+// Tickets already imported are skipped; any invalid row or missing stock aborts
+// the whole import without modifying the store.
+import { isDate } from "../dates.js";
+import { AppError } from "../errors.js";
+import { consume } from "../domain/batches.js";
+import { getItem, onHand } from "../domain/items.js";
+import { getRecipe, scaled } from "../domain/recipes.js";
+import { parseCsv } from "./csv.js";
+
+const HEADER = ["ticket", "soldAt", "dishId", "qty"];
+const INSTANT = /^(\d{4}-\d{2}-\d{2})T(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d+)?(?:Z|[+-]\d{2}:\d{2})$/;
+
+function parseInstant(s) {
+  const m = INSTANT.exec(s);
+  if (!m || !isDate(m[1])) return null;
+  const ms = Date.parse(s);
+  return Number.isNaN(ms) ? null : new Date(ms).toISOString();
+}
+
+/** Imports sales from CSV; returns { tickets, dishes } counts or throws naming the row. */
+export function importSales(store, text) {
+  const [head = [], ...rawRows] = parseCsv(text);
+  if (head.length === 0) return { tickets: 0, dishes: 0 };
+  const keys = head.map((h) => h.trim());
+  for (const k of HEADER) {
+    if (!keys.includes(k)) throw new AppError("bad_request", { reason: `missing column ${k}` });
+  }
+  const dishes = store.data.dishes ?? [];
+  const parsed = rawRows.map((cells, i) => {
+    const where = `row ${i + 2}`;
+    const r = Object.fromEntries(keys.map((k, idx) => [k, (cells[idx] ?? "").trim()]));
+    if (!r.ticket) throw new AppError("bad_request", { reason: `${where}: ticket is required` });
+    const soldAt = parseInstant(r.soldAt);
+    if (!soldAt) throw new AppError("bad_request", { reason: `${where}: bad soldAt` });
+    const dishId = Number(r.dishId);
+    if (!Number.isInteger(dishId) || dishId < 1) throw new AppError("bad_request", { reason: `${where}: bad dishId` });
+    const dish = dishes.find((d) => d.id === dishId);
+    if (!dish) throw new AppError("bad_request", { reason: `${where}: unknown dish ${dishId}` });
+    const qty = Number(r.qty);
+    if (!Number.isInteger(qty) || qty < 1) throw new AppError("bad_request", { reason: `${where}: bad qty` });
+    const recipe = getRecipe(store, dish.recipeId);
+    return { where, ticket: r.ticket, soldAt, dishId, qty, needs: scaled(recipe, qty) };
+  });
+
+  const existingTickets = new Set((store.data.sales ?? []).map((s) => s.ticket));
+  const toImport = parsed.filter((row) => !existingTickets.has(row.ticket));
+
+  const available = new Map();
+  for (const row of toImport) {
+    for (const n of row.needs) {
+      const item = getItem(store, n.itemId);
+      const avail = available.has(n.itemId) ? available.get(n.itemId) : onHand(store, n.itemId);
+      if (avail < n.qty) {
+        throw new AppError("import_not_enough_stock", {
+          where: row.where,
+          item: item.name,
+          available: avail,
+          unit: item.unit,
+        });
+      }
+      available.set(n.itemId, Math.round((avail - n.qty) * 1000) / 1000);
+    }
+  }
+
+  store.data.sales ??= [];
+  const importedTickets = new Set();
+  let dishCount = 0;
+  for (const row of toImport) {
+    for (const n of row.needs) {
+      if (n.qty > 0) consume(store, n.itemId, n.qty, { at: row.soldAt, ref: `sale:${row.ticket}` });
+    }
+    store.data.sales.push({
+      id: store.nextId("sale"),
+      ticket: row.ticket,
+      soldAt: row.soldAt,
+      dishId: row.dishId,
+      qty: row.qty,
+    });
+    importedTickets.add(row.ticket);
+    dishCount += row.qty;
+  }
+  return { tickets: importedTickets.size, dishes: dishCount };
+}
